select o.id, o.city, o.sqft
from stores o
where o.sqft > 0.8 * (select avg(i.sqft) from stores i where i.city = o.city);

select sale_date, product_id, units from store_sales
intersect
select sale_date, product_id, units from store_sales where revenue is not null;

SELECT o.id, o.country, o.age, o.email
FROM customers o
WHERE o.age > 1.2 * (SELECT AVG(i.age) FROM customers i WHERE i.country = o.country);

SELECT c.id, c.age
FROM customers c
