SELECT a.id, a.country, a.rating, a.supplier_name, (SELECT MIN(x.rating) FROM suppliers AS x WHERE x.country = 'DE') AS overall_min_rating, a.rating - (SELECT MAX(b.rating) FROM suppliers AS b WHERE a.country = b.country) AS diff_from_country_max
FROM suppliers AS a
ORDER BY rating;

